#include <stdlib.h>
#include <math.h>
#include <string.h>
/* sparse shortest augmenting path LAP. returns 0 ok, 1 infeasible */
static int solve_sparse(int n, const double*C, const int*ptr, const int*idx,
    double*u, double*v, int*col4row, int*row4col){
  double *d=malloc(n*sizeof(double)); int *path=malloc(n*sizeof(int));
  char *SR=calloc(n,1), *SC=calloc(n,1);
  int *touchedC=malloc(n*sizeof(int)), *rowsR=malloc(n*sizeof(int));
  int hcap=ptr[n]+16; double *hk=malloc(hcap*sizeof(double)); int *hv=malloc(hcap*sizeof(int));
  int ret=0;
  for(int j=0;j<n;j++){d[j]=INFINITY;row4col[j]=-1;}
  for(int i=0;i<n;i++){col4row[i]=-1;u[i]=0;}
  for(int j=0;j<n;j++){v[j]=INFINITY;}
  for(int i=0;i<n;i++) for(int e=ptr[i];e<ptr[i+1];e++){int j=idx[e]; double c=C[(size_t)i*n+j]; if(c<v[j])v[j]=c;}
  for(int j=0;j<n;j++) if(!isfinite(v[j])) v[j]=0;
  for(int cur=0;cur<n;cur++){
    int nt=0,nr=0,hs=0; double minVal=0; int i=cur,sink=-1;
    while(1){
      SR[i]=1; rowsR[nr++]=i;
      const double*Ci=C+(size_t)i*n; double ui=u[i];
      for(int e=ptr[i];e<ptr[i+1];e++){int j=idx[e]; if(SC[j])continue;
        double r=minVal+Ci[j]-ui-v[j];
        if(r<d[j]){ if(d[j]==INFINITY) touchedC[nt++]=j; d[j]=r; path[j]=i;
          /* push */ int p=hs++; if(hs>hcap){hcap*=2;hk=realloc(hk,hcap*sizeof(double));hv=realloc(hv,hcap*sizeof(int));}
          while(p>0){int q=(p-1)>>1; if(hk[q]<=r)break; hk[p]=hk[q];hv[p]=hv[q];p=q;} hk[p]=r;hv[p]=j; }
      }
      int jm=-1;
      while(hs>0){ double k0=hk[0]; int j0=hv[0];
        /* pop */ hs--; double lk=hk[hs]; int lv=hv[hs]; int p=0;
        while(1){int c=2*p+1; if(c>=hs)break; if(c+1<hs&&hk[c+1]<hk[c])c++; if(hk[c]>=lk)break; hk[p]=hk[c];hv[p]=hv[c];p=c;}
        if(hs>0){hk[p]=lk;hv[p]=lv;}
        if(SC[j0]||k0>d[j0])continue; jm=j0;break; }
      if(jm<0){ret=1;break;}
      minVal=d[jm]; SC[jm]=1;
      if(row4col[jm]==-1){sink=jm;break;}
      i=row4col[jm];
    }
    if(ret){ for(int t=0;t<nt;t++){SC[touchedC[t]]=0;} for(int t=0;t<nr;t++)SR[rowsR[t]]=0; break;}
    u[cur]+=minVal;
    for(int t=0;t<nr;t++){int r=rowsR[t]; if(r!=cur) u[r]+=minVal-d[col4row[r]]; SR[r]=0;}
    for(int t=0;t<nt;t++){int j=touchedC[t]; if(SC[j]){v[j]-=minVal-d[j];SC[j]=0;} d[j]=INFINITY;}
    int j=sink;
    while(1){int r=path[j]; row4col[j]=r; int tmp=col4row[r]; col4row[r]=j; j=tmp; if(r==cur)break;}
  }
  free(d);free(path);free(SR);free(SC);free(touchedC);free(rowsR);free(hk);free(hv);
  return ret;
}
/* main entry: C dense n x n. returns col4row. */
int lap(int n, const double*C, int k, int*col4row){
  if(k>n)k=n;
  int *row4col=malloc(n*sizeof(int)); double*u=malloc(n*sizeof(double)),*v=malloc(n*sizeof(double));
  char *E=calloc((size_t)n*n,1);
  double *bk=malloc((k+1)*sizeof(double)); int *bj=malloc((k+1)*sizeof(int));
  /* row kNN */
  for(int i=0;i<n;i++){const double*Ci=C+(size_t)i*n; int m=0;
    for(int j=0;j<n;j++){double c=Ci[j]; if(m==k&&c>=bk[m-1])continue; int p=(m<k)?m++:m-1;
      while(p>0&&bk[p-1]>c){bk[p]=bk[p-1];bj[p]=bj[p-1];p--;} bk[p]=c;bj[p]=j;}
    for(int t=0;t<m;t++)E[(size_t)i*n+bj[t]]=1;}
  /* column kNN */
  {double*ck=malloc((size_t)k*n*sizeof(double)); int*ci=malloc((size_t)k*n*sizeof(int)); int*cm=calloc(n,sizeof(int));
   for(int i=0;i<n;i++){const double*Ci=C+(size_t)i*n;
     for(int j=0;j<n;j++){double c=Ci[j]; int m=cm[j]; double*K=ck+(size_t)j*k; int*I=ci+(size_t)j*k;
       if(m==k&&c>=K[m-1])continue; int p=(m<k)?m++:m-1; cm[j]=m;
       while(p>0&&K[p-1]>c){K[p]=K[p-1];I[p]=I[p-1];p--;} K[p]=c;I[p]=i;}}
   for(int j=0;j<n;j++)for(int t=0;t<cm[j];t++)E[(size_t)ci[(size_t)j*k+t]*n+j]=1;
   free(ck);free(ci);free(cm);}
  int ret=-1;
  for(int iter=0;iter<50;iter++){
    int *ptr=malloc((n+1)*sizeof(int)); size_t ne=0;
    for(int i=0;i<n;i++){ptr[i]=ne; for(int j=0;j<n;j++) ne+=E[(size_t)i*n+j];} ptr[n]=ne;
    int *idx=malloc((ne+1)*sizeof(int)); size_t q=0;
    for(int i=0;i<n;i++)for(int j=0;j<n;j++)if(E[(size_t)i*n+j])idx[q++]=j;
    int r=solve_sparse(n,C,ptr,idx,u,v,col4row,row4col);
    free(ptr);free(idx);
    if(r){ /* infeasible: densify */ memset(E,1,(size_t)n*n); continue; }
    /* verify duals */
    int bad=0;
    for(int i=0;i<n;i++){const double*Ci=C+(size_t)i*n; double ui=u[i]; char*Ei=E+(size_t)i*n;
      for(int j=0;j<n;j++){ if(Ci[j]-ui-v[j] < -1e-12){ if(!Ei[j]){Ei[j]=1;bad++;} } }}
    if(!bad){ret=iter;break;}
  }
  free(row4col);free(u);free(v);free(E);free(bk);free(bj);
  return ret;
}
