import os, ctypes, hashlib, subprocess
import numpy as np

_here = os.path.dirname(os.path.abspath(__file__))
from lap_src import SRC as _SRC  # noqa

def _load():
    h = hashlib.md5(_SRC.encode()).hexdigest()[:10]
    so = os.path.join(_here, f"_lap_{h}.so")
    if not os.path.exists(so):
        bd = os.path.join(_here, "build"); os.makedirs(bd, exist_ok=True)
        c = os.path.join(bd, "lap.c")
