        subprocess.check_call(["cc", "-O3", "-shared", "-fPIC", "-o", so, c], env=env)
    lib = ctypes.CDLL(so)
    lib.lap.restype = ctypes.c_int
    lib.lap.argtypes = [ctypes.c_int, ctypes.c_void_p, ctypes.c_int, ctypes.c_void_p]
    return lib

try:
    _lib = _load()
