  int ret=0;
  for(int j=0;j<n;j++){v[j]=INF;y[j]=-1;row4col[j]=-1;d[j]=INF;}
  for(int i=0;i<n;i++)col4row[i]=-1;
  for(int i=n-1;i>=0;i--) for(int e=ptr[i];e<ptr[i+1];e++){int j=idx[e]; if(cc[e]<v[j]){v[j]=cc[e];y[j]=i;}}
  for(int j=0;j<n;j++) if(y[j]<0){ret=1;goto done;}
  for(int j=n-1;j>=0;j--){int i=y[j]; if(++matches[i]==1){col4row[i]=j;row4col[j]=i;} }
